-- Recovered from the linked project's Supabase migration history.

-- Back to Us playable V2: 365 active cards, 4,135 preserved archived cards.
begin;

create temporary table decked_back_to_us_v2_active(item_id uuid primary key,category_id text not null,sort_order integer not null,body text not null,metadata jsonb not null,revised boolean not null) on commit drop;


do $$ declare matched integer; begin select count(*) into matched from public.content_items item join decked_back_to_us_v2_active selected on selected.item_id=item.id where item.game_id='reconnect'; if matched<>365 then raise exception 'Back to Us V2 inventory mismatch: expected 365 IDs, found %',matched; end if; end $$;

update public.content_items set lifecycle_status='archived',updated_at=now() where game_id='reconnect';

update public.content_items item set lifecycle_status='active',updated_at=now() from decked_back_to_us_v2_active selected where item.id=selected.item_id and item.game_id='reconnect';

update public.content_categories set enabled=(category_id in ('partner/light','partner/meaningful','partner/deep','friends/light','friends/meaningful','friends/deep','family/light','family/meaningful','family/deep')),target_count=case when category_id='partner/light' then 37 when category_id='partner/meaningful' then 49 when category_id='partner/deep' then 32 when category_id='friends/light' then 45 when category_id='friends/meaningful' then 52 when category_id='friends/deep' then 30 when category_id='family/light' then 46 when category_id='family/meaningful' then 44 when category_id='family/deep' then 30 else target_count end,updated_at=now() where game_id='reconnect';

update public.content_item_categories set enabled=false where game_id='reconnect';


create temporary table decked_back_to_us_v2_revisions on commit drop as select selected.*,item.current_version+1 next_version from decked_back_to_us_v2_active selected join public.content_items item on item.id=selected.item_id where selected.revised;

update public.content_item_versions version set editorial_status='superseded' from decked_back_to_us_v2_revisions revised where version.item_id=revised.item_id and version.version=(select published_version from public.content_items where id=revised.item_id);


update public.content_items item set current_version=revised.next_version,published_version=revised.next_version,updated_at=now() from decked_back_to_us_v2_revisions revised where item.id=revised.item_id;

update public.content_item_versions version set metadata=coalesce(version.metadata,'{}'::jsonb)||selected.metadata from decked_back_to_us_v2_active selected join public.content_items item on item.id=selected.item_id where not selected.revised and version.item_id=item.id and version.version=item.published_version;

update public.content_releases set status='superseded' where game_id='reconnect' and status='published';


delete from public.content_release_items where release_id='0237c0b0-645b-573c-886f-669b6bc26951'::uuid;


commit;
